def get_perimeter(n):
    flooded = set()
    for x in range(-n, n + 1):
        for y in range(-n, n + 1):
            if abs(x) + abs(y) <= n:
                flooded.add((x, y))

    perimeter = 0
    for (x, y) in flooded:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in flooded:
                perimeter += 1
    return perimeter

for n in range(1, 11):
