def get_perimeter_k_n(K, N):
    # S0 is a K x K square
    S0 = set()
    for x in range(K):
        for y in range(K):
            S0.add((x, y))

    # Flood for N steps
    flooded = set(S0)
    for _ in range(N):
        new_flooded = set()
        for (x, y) in flooded:
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if (nx, ny) not in flooded:
                    new_flooded.add((nx, ny))
        flooded.update(new_flooded)

